import {
  createIDNAError,
  createInvalidCodepointError,
  createJoinerError,
} from "./errors.mjs";

const ASCII_ONLY_RE = /^[\x00-\x7F]*$/;
const ASCII_LABEL_CHAR_RE = /^[A-Za-z0-9-]$/;
const LOWER_ASCII_LABEL_CHAR_RE = /^[a-z0-9-]$/;
const MARK_RE = /^\p{M}$/u;
const LOWERCASE_LETTER_RE = /^\p{Ll}$/u;
const MODIFIER_LETTER_RE = /^\p{Lm}$/u;
const OTHER_LETTER_RE = /^\p{Lo}$/u;
const NONSPACING_MARK_RE = /^\p{Mn}$/u;
const SPACING_MARK_RE = /^\p{Mc}$/u;
const DECIMAL_NUMBER_RE = /^\p{Nd}$/u;
const GREEK_RE = /^\p{Script=Greek}$/u;
const HEBREW_RE = /^\p{Script=Hebrew}$/u;
const HIRAGANA_RE = /^\p{Script=Hiragana}$/u;
const KATAKANA_RE = /^\p{Script=Katakana}$/u;
const HAN_RE = /^\p{Script=Han}$/u;

function hasLeadingOrTrailingHyphen(label) {
  return label.startsWith("-") || label.endsWith("-");
}

function hasDisallowedDoubleHyphen(label) {
  return label.length >= 4 && label[2] === "-" && label[3] === "-";
}

function isNonAsciiAllowed(character) {
  return (
    LOWERCASE_LETTER_RE.test(character) ||
    MODIFIER_LETTER_RE.test(character) ||
    OTHER_LETTER_RE.test(character) ||
    NONSPACING_MARK_RE.test(character) ||
    SPACING_MARK_RE.test(character) ||
    DECIMAL_NUMBER_RE.test(character)
  );
}

function labelCodePoints(label) {
  return Array.from(label);
}

function ensureNotEmpty(label) {
  if (label === "") {
    throw createIDNAError("Empty Label");
  }
}

function ensureAsciiLength(label) {
  if (label.length > 63) {
    throw createIDNAError("Label too long");
  }
}

function ensureHyphenRules(label, { allowAcePrefix }) {
  if (allowAcePrefix && /^xn--/i.test(label) && label.length === 4) {
    throw createIDNAError("Malformed A-label, no Punycode eligible content found");
  }

  if (allowAcePrefix && /^xn--/i.test(label) && label.endsWith("-")) {
    throw createIDNAError("A-label must not end with a hyphen");
  }

  if (hasLeadingOrTrailingHyphen(label)) {
    throw createIDNAError("Label must not start or end with a hyphen");
  }

  if (hasDisallowedDoubleHyphen(label) && !(allowAcePrefix && /^xn--/i.test(label))) {
    throw createIDNAError("Label has disallowed hyphens in 3rd and 4th position");
  }
}

function ensureNormalization(label) {
  if (label.normalize("NFC") !== label) {
    throw createIDNAError("Label must be in Normalization Form C");
  }
}

function ensureNoLeadingCombiningMark(characters) {
  if (characters.length > 0 && MARK_RE.test(characters[0])) {
    throw createIDNAError("Label begins with an illegal combining character");
  }
}

function ensureContextualCodePoint(label, characters, index, character) {
  if (character === "\u00B7") {
    if (characters[index - 1] === "l" && characters[index + 1] === "l") {
      return;
    }
    throw createInvalidCodepointError(character, index + 1, label);
  }

  if (character === "\u0375") {
    if (characters[index + 1] && GREEK_RE.test(characters[index + 1])) {
      return;
    }
    throw createInvalidCodepointError(character, index + 1, label);
  }

  if (character === "\u05F3" || character === "\u05F4") {
    if (characters[index - 1] && HEBREW_RE.test(characters[index - 1])) {
      return;
    }
    throw createInvalidCodepointError(character, index + 1, label);
  }

  if (character === "\u30FB") {
    const hasJapaneseScript = characters.some(
      (candidate) =>
        HIRAGANA_RE.test(candidate) ||
        KATAKANA_RE.test(candidate) ||
        HAN_RE.test(candidate)
    );
    if (hasJapaneseScript) {
      return;
    }
    throw createInvalidCodepointError(character, index + 1, label);
  }

  if (character === "\u200C" || character === "\u200D") {
    throw createJoinerError(character, index + 1, label);
  }

  throw createInvalidCodepointError(character, index + 1, label);
}

export function isASCIIOnly(value) {
  return ASCII_ONLY_RE.test(value);
}

export function splitDomain(domain, strict = false) {
  const normalizedDomain = strict
    ? domain
    : domain.replace(/[\u3002\uFF0E\uFF61]/g, ".");
  const labels = normalizedDomain.split(".");
  const hasTrailingDot = labels.length > 1 && labels[labels.length - 1] === "";

  if (hasTrailingDot) {
    labels.pop();
  }

  return { labels, hasTrailingDot };
}

export function validateAsciiLabel(label) {
  ensureNotEmpty(label);
  ensureAsciiLength(label);
  ensureHyphenRules(label, { allowAcePrefix: true });

  const characters = labelCodePoints(label);
  for (let index = 0; index < characters.length; index += 1) {
    if (!ASCII_LABEL_CHAR_RE.test(characters[index])) {
      throw createInvalidCodepointError(characters[index], index + 1, label);
    }
  }
}

export function validateUnicodeLabel(label) {
  ensureNotEmpty(label);
  ensureNormalization(label);
  ensureHyphenRules(label, { allowAcePrefix: false });

  const characters = labelCodePoints(label);
  ensureNoLeadingCombiningMark(characters);

  let hasArabicIndicDigits = false;
  let hasExtendedArabicIndicDigits = false;

  for (let index = 0; index < characters.length; index += 1) {
    const character = characters[index];
    const codePoint = character.codePointAt(0);

    if (codePoint <= 0x7f) {
      if (!LOWER_ASCII_LABEL_CHAR_RE.test(character)) {
        throw createInvalidCodepointError(character, index + 1, label);
      }
      continue;
    }

    if (codePoint >= 0x0660 && codePoint <= 0x0669) {
      hasArabicIndicDigits = true;
    }

    if (codePoint >= 0x06F0 && codePoint <= 0x06F9) {
      hasExtendedArabicIndicDigits = true;
    }

    if (isNonAsciiAllowed(character)) {
      continue;
    }

    ensureContextualCodePoint(label, characters, index, character);
  }

  if (hasArabicIndicDigits && hasExtendedArabicIndicDigits) {
    const offendingCharacter = characters.find((character) => {
      const codePoint = character.codePointAt(0);
      return codePoint >= 0x06F0 && codePoint <= 0x06F9;
    });
    const offendingIndex = characters.findIndex((character) => character === offendingCharacter);
    throw createInvalidCodepointError(offendingCharacter, offendingIndex + 1, label);
  }
}

