import { pythonStringRepr } from "../python-format.mjs";

export class IDNAError extends Error {
  constructor(message) {
    super(message);
    this.name = "IDNAError";
  }
}

export class InvalidCodepointError extends IDNAError {
  constructor(message) {
    super(message);
    this.name = "InvalidCodepoint";
  }
}

export function codePointHex(character) {
  return character.codePointAt(0).toString(16).toUpperCase().padStart(4, "0");
}

export function createIDNAError(message) {
  return new IDNAError(message);
}

export function createInvalidCodepointError(character, position, label) {
  return new InvalidCodepointError(
    `Codepoint U+${codePointHex(character)} at position ${position} of ${pythonStringRepr(label)} not allowed`
  );
}

export function createJoinerError(character, position, label) {
  return new InvalidCodepointError(
    `Unknown codepoint adjacent to joiner U+${codePointHex(character)} at position ${position} in ${pythonStringRepr(label)}`
  );
}

