import { decode as punycodeDecode, encode as punycodeEncode } from "./punycode.mjs";
import { createIDNAError } from "./errors.mjs";
import {
  isASCIIOnly,
  splitDomain,
  validateAsciiLabel,
  validateUnicodeLabel,
} from "./validation.mjs";

function decodeALabel(label) {
  if (label.length === 4) {
    throw createIDNAError("Malformed A-label, no Punycode eligible content found");
  }

  let decoded;
  try {
    decoded = punycodeDecode(label.slice(4).toLowerCase());
  } catch (error) {
    throw createIDNAError(error.message);
  }

  validateUnicodeLabel(decoded);

  const roundTrip = `xn--${punycodeEncode(decoded)}`;
  if (roundTrip.toLowerCase() !== label.toLowerCase()) {
    throw createIDNAError("Invalid A-label");
  }

  return decoded;
}

export function alabel(label) {
  if (isASCIIOnly(label)) {
    validateAsciiLabel(label);
    if (/^xn--/i.test(label)) {
      decodeALabel(label);
    }
    return label;
  }

  validateUnicodeLabel(label);
  const encoded = `xn--${punycodeEncode(label)}`;
  if (encoded.length > 63) {
    throw createIDNAError("Label too long");
  }
  return encoded;
}

export function ulabel(label) {
  if (!isASCIIOnly(label)) {
    validateUnicodeLabel(label);
    return label;
  }

  validateAsciiLabel(label);
  if (!/^xn--/i.test(label)) {
    return label;
  }

  return decodeALabel(label);
}

export function encode(domain, options = {}) {
  const strict = options.strict ?? false;
  const { labels, hasTrailingDot } = splitDomain(domain, strict);

  if (labels.length === 0) {
    throw createIDNAError("Empty Label");
  }

  const encodedLabels = labels.map((label) => alabel(label));
  const encodedDomain = encodedLabels.join(".");
  return hasTrailingDot ? `${encodedDomain}.` : encodedDomain;
}

