function isPrintableCharacter(character) {
  if (character === " ") {
    return true;
  }

  return !/[\p{C}\p{Z}]/u.test(character);
}

function escapeCodePoint(codePoint) {
  if (codePoint <= 0xff) {
    return `\\x${codePoint.toString(16).padStart(2, "0")}`;
  }

  if (codePoint <= 0xffff) {
    return `\\u${codePoint.toString(16).padStart(4, "0")}`;
  }

  return `\\U${codePoint.toString(16).padStart(8, "0")}`;
}

export function escapePythonStringContent(value) {
  let result = "";

  for (const character of Array.from(value)) {
    const codePoint = character.codePointAt(0);

    if (character === "\\") {
      result += "\\\\";
      continue;
    }

    if (character === "'") {
      result += "\\'";
      continue;
    }

    if (character === "\n") {
      result += "\\n";
      continue;
    }

    if (character === "\r") {
      result += "\\r";
      continue;
    }

    if (character === "\t") {
      result += "\\t";
      continue;
    }

    if (isPrintableCharacter(character)) {
      result += character;
      continue;
    }

    result += escapeCodePoint(codePoint);
  }

  return result;
}

export function pythonStringRepr(value) {
  return `'${escapePythonStringContent(value)}'`;
}

export function pythonBytesRepr(value) {
  return `b'${escapePythonStringContent(value)}'`;
}

export function pythonBoolLiteral(value) {
  return value ? "True" : "False";
}

